import json, sys, collections

VALID_TIPO = {"bug", "enhancement", "documentation"}
VALID_SUP = {"app", "CLI", "extension", "codex-web", "iOS"}
VALID_AREAS = {"windows-os","sandbox","app-server","connectivity","TUI","session","rate-limits","tool-calls","browser","remote","model-behavior","performance","mcp","auth","context","subagent","config","computer-use"}

with open('incidencias.jsonl') as f:
    src = [json.loads(l) for l in f]
src_ids = [d['id'] for d in src]

out = {}
for i in range(6):
    path = f'/tmp/opencode/clasif/out_{i}.jsonl'
    try:
        with open(path) as f:
            for ln, l in enumerate(f, 1):
                l = l.strip()
                if not l:
                    continue
                d = json.loads(l)
                assert set(d) == {"id","tipo","superficie","areas"}, f"{path}:{ln} claves {set(d)}"
                out[d['id']] = d
    except FileNotFoundError:
        print(f"FALTA {path}")

errors = []
for id_ in src_ids:
    if id_ not in out:
        errors.append(f"falta {id_}")
        continue
    d = out[id_]
    if d['tipo'] not in VALID_TIPO: errors.append(f"{id_} tipo inválido: {d['tipo']}")
    if d['superficie'] not in VALID_SUP: errors.append(f"{id_} superficie inválida: {d['superficie']}")
    if not isinstance(d['areas'], list) or not d['areas']:
        errors.append(f"{id_} areas vacías/no lista")
    else:
        for a in d['areas']:
            if a not in VALID_AREAS: errors.append(f"{id_} área inválida: {a}")
        if len(set(d['areas'])) != len(d['areas']): errors.append(f"{id_} áreas duplicadas")

if errors:
    print("ERRORES:")
    for e in errors: print(" ", e)
    sys.exit(1)

with open('clasificacion.jsonl', 'w') as f:
    for id_ in src_ids:
        f.write(json.dumps(out[id_], ensure_ascii=False) + "\n")

print("OK: 300 líneas escritas en clasificacion.jsonl")
print("tipo:", collections.Counter(out[i]['tipo'] for i in src_ids))
print("superficie:", collections.Counter(out[i]['superficie'] for i in src_ids))
ac = collections.Counter(a for i in src_ids for a in out[i]['areas'])
print("areas:", ac.most_common())
